            .core
            .catalog()
            .plugins()
            .iter()
            .map(|p| PluginInfo {
                id: p.id.clone(),
                name: p.name.clone(),
                version: p.version.clone(),
                description: p.description.clone(),
                dbus_path: p.dbus_path.clone(),
                interfaces: p.interfaces.clone(),
                tags: p.tags.clone(),
            })
