 88	fn deep_merge(
 89	    base: &mut serde_json::Map<String, serde_json::Value>,
 90	    patch: &serde_json::Map<String, serde_json::Value>,
 91	) {
 92	    for (key, value) in patch {
 93	        match (base.get_mut(key), value) {
 94	            (Some(serde_json::Value::Object(b)), serde_json::Value::Object(p)) => {
 95	                deep_merge(b, p);
 96	            }
 97	            _ => {
 98	                base.insert(key.clone(), value.clone());
 99	            }
100	        }
101	    }
102	}
