116	/// In-memory object state, keyed by `(plugin_id, object_path)`.
117	#[derive(Debug, Default)]
118	pub struct StateStore {
119	    inner: RwLock<StateStoreInner>,
120	}
121	
122	impl StateStore {
123	    /// An empty store at generation 0.
124	    pub fn new() -> Self {
125	        Self::default()
126	    }
127	
128	    /// Current generation (bumped by every accepted state write).
129	    pub fn generation(&self) -> u64 {
130	        self.inner.read().expect("store lock poisoned").generation
131	    }
132	
133	    fn hash_map(map: &serde_json::Map<String, serde_json::Value>) -> String {
134	        blake3::hash(&canonical_json(&serde_json::Value::Object(map.clone())))
135	            .to_hex()
136	            .to_string()
137	    }
138	
139	    /// Whole-object read plus its effective hash.
140	    pub fn get_object(
141	        &self,
142	        plugin_id: &str,
143	        object_path: &str,
144	    ) -> Option<(serde_json::Map<String, serde_json::Value>, String)> {
145	        let inner = self.inner.read().expect("store lock poisoned");
146	        inner
147	            .objects
148	            .get(&(plugin_id.to_owned(), object_path.to_owned()))
149	            .map(|map| (map.clone(), Self::hash_map(map)))
150	    }
151	
152	    /// Single-member read.
153	    pub fn get_member(
154	        &self,
155	        plugin_id: &str,
156	        object_path: &str,
157	        member: &str,
158	    ) -> Option<serde_json::Value> {
159	        self.inner
160	            .read()
161	            .expect("store lock poisoned")
162	            .objects
163	            .get(&(plugin_id.to_owned(), object_path.to_owned()))
164	            .and_then(|map| map.get(member).cloned())
165	    }
166	
167	    /// Effective (content) hash of one object, if present.
168	    pub fn effective_hash(&self, plugin_id: &str, object_path: &str) -> Option<String> {
169	        self.inner
170	            .read()
171	            .expect("store lock poisoned")
172	            .objects
173	            .get(&(plugin_id.to_owned(), object_path.to_owned()))
174	            .map(Self::hash_map)
175	    }
176	
177	    /// Set one member (creating the object if needed). Returns the previous
178	    /// value, if any, and the new effective hash. Bumps the generation.
179	    pub fn set_member(
180	        &self,
181	        plugin_id: &str,
182	        object_path: &str,
183	        member: &str,
184	        value: serde_json::Value,
185	    ) -> (Option<serde_json::Value>, String) {
186	        let mut inner = self.inner.write().expect("store lock poisoned");
187	        let map = inner
188	            .objects
189	            .entry((plugin_id.to_owned(), object_path.to_owned()))
190	            .or_default();
191	        let old = map.insert(member.to_owned(), value);
192	        let hash = Self::hash_map(map);
193	        inner.generation += 1;
194	        (old, hash)
195	    }
196	
197	    /// Deep-merge an object patch (creating the object if needed). Returns the
198	    /// new effective hash. Bumps the generation.
199	    pub fn apply_patch(
200	        &self,
201	        plugin_id: &str,
202	        object_path: &str,
203	        patch: &serde_json::Map<String, serde_json::Value>,
204	    ) -> String {
205	        let mut inner = self.inner.write().expect("store lock poisoned");
206	        let map = inner
207	            .objects
208	            .entry((plugin_id.to_owned(), object_path.to_owned()))
209	            .or_default();
210	        deep_merge(map, patch);
211	        let hash = Self::hash_map(map);
212	        inner.generation += 1;
213	        hash
214	    }
215	
216	    /// Every object, sorted by `(plugin_id, object_path)`.
217	    pub fn snapshot(&self) -> Vec<(String, String, serde_json::Map<String, serde_json::Value>)> {
218	        let inner = self.inner.read().expect("store lock poisoned");
219	        let mut out: Vec<_> = inner
220	            .objects
221	            .iter()
222	            .map(|((plugin, path), map)| (plugin.clone(), path.clone(), map.clone()))
223	            .collect();
224	        out.sort_by(|a, b| (&a.0, &a.1).cmp(&(&b.0, &b.1)));
225	        out
226	    }
227	}
