//! Catalog routing: match a request against nested catalogs, then decide.
//!
//! Pipeline (`docs/DROP-IN-SPEC.md` §2.2): adapter → [`decide`] → enforcement.
//! This crate computes the decision only. Enforcement (mount call files,
//! receipts) stays with the bridge; grants come from the compiled profile.
//!
//! ```text
//! Request { actor, surface, action, tags }
//!   → catalogs::compliance::match_controls  (tags → controls → operations)
//!   → catalogs::ui::check                   (target support, degradation)
//!   → catalogs::models::select              (provider/model for the turn)
//!   → decide                               (allow | refuse | needs-approval)
//! ```

pub mod acceptance;
pub mod catalogs;
pub mod decide;
pub mod model;
pub mod org_bridge;

pub use decide::decide;
pub use model::{ActionKind, Decision, Grants, Profile, Request, Surface, Verdict};
//! Request, grants, and decision types: `routing/DATA-MODEL.md` "Types".

use serde::{Deserialize, Serialize};

/// Renderer target. Web is the reference renderer; team chat is the first
/// drop-in target (`docs/DROP-IN-SPEC.md` §2.1). Teams and email are planned.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Surface {
    Web,
    TeamChat,
    Teams,
    Email,
}

/// What the request does. Qualifier tags use the same words
/// (`action:read`, `action:write`, `action:publish`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum ActionKind {
    Read,
    Write,
    Publish,
}

/// Adapter output. `tags` carries ≥1 control tag (`oscal/TAG-TAXONOMY.md`)
/// plus qualifier tags (`action:*`, `approval:root`, `surface:*`, `model:*`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Request {
    pub actor: String,
    pub surface: Surface,
    pub action: ActionKind,
    pub tags: Vec<String>,
    pub payload_ref: String,
}

/// Compiled profile: which controls apply. Grants (authority) arrive
/// separately — tags never grant (`oscal/TAG-TAXONOMY.md` rules).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Profile {
    pub id: String,
    pub controls: Vec<String>,
}
/// The identity's compiled grants: exact sealed capability strings.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Grants {
    pub capabilities: Vec<String>,
}

impl Grants {
    /// Sealed capabilities are opaque strings: exact match only.
    pub fn covers(&self, capability: &str) -> bool {
        self.capabilities.iter().any(|c| c == capability)
    }
}

/// A candidate plugin operation: `operations/<plugin>/<method>/call`.
///
/// `capability` is the exact sealed capability (`opblob inspect`), or
/// `None` when no blob is sealed for the method yet — a method exists if
/// and only if its blob is in the sealed catalog.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Operation {
    pub plugin: String,
    pub method: String,
    pub capability: Option<String>,
}

/// The verdict. Refusals name the missing capability and the rule;
/// root actions need two different humans (mirrors `approvals/`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum Verdict {
    Allow,
    Refuse {
        missing_capability: Option<String>,
        rule: String,
    },
    NeedsApproval {
        have: u32,
        need: u32,
        rule: String,
    },
}

/// The decision: candidate operations plus the verdict on them.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Decision {
    pub operations: Vec<Operation>,
    pub verdict: Verdict,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn grants_cover_exact_capability_only() {
        let grants = Grants {
            capabilities: vec!["cron.invoke".into()],
        };
        assert!(grants.covers("cron.invoke"));
        assert!(!grants.covers("cron.read"));
        assert!(!grants.covers("cron"));
    }

    #[test]
    fn operation_carries_sealed_capability() {
        let op = Operation {
            plugin: "cron".into(),
            method: "create_job".into(),
            capability: Some("cron.invoke".into()),
        };
        assert_eq!(op.capability.as_deref(), Some("cron.invoke"));
    }
}
//! The decision: allow / refuse / needs-approval.
//!
//! Order (`docs/DROP-IN-SPEC.md` §2.2, `routing/DATA-MODEL.md`): match
//! controls → root needs two humans → fail closed on unsealed methods →
//! allow the grant-covered subset. A control miss refuses before grants
//! are consulted; grants never come from tags.

use crate::catalogs::compliance;
use crate::model::{Decision, Grants, Profile, Request, Verdict};

/// Pure decision over a request, profile controls, and compiled grants.
pub fn decide(request: &Request, profile: &Profile, grants: &Grants) -> Decision {
    let matches = compliance::match_controls(&request.tags, &profile.controls);
    if matches.is_empty() {
        return Decision {
            operations: vec![],
            verdict: Verdict::Refuse {
                missing_capability: None,
                rule: "no-control-match".to_string(),
            },
        };
    }
    let operations: Vec<_> = matches.iter().flat_map(|m| m.operations.clone()).collect();

    if compliance::is_root(&request.tags) {
        return Decision {
            operations,
            verdict: Verdict::NeedsApproval {
                have: 0,
                need: 2,
                rule: "two-person-root".to_string(),
            },
        };
    }

    for op in &operations {
        if op.capability.is_none() {
            return Decision {
                operations: vec![],
                verdict: Verdict::Refuse {
                    missing_capability: None,
                    rule: format!("method-not-sealed:{}.{}", op.plugin, op.method),
                },
            };
        }
    }

    let (covered, uncovered): (Vec<_>, Vec<_>) = operations.into_iter().partition(|op| {
        op.capability
            .as_deref()
            .is_some_and(|cap| grants.covers(cap))
    });
    if covered.is_empty() {
        let op = &uncovered[0];
        let capability = op.capability.clone().unwrap_or_default();
        let rule = matches
            .iter()
            .find(|m| {
                m.operations
                    .iter()
                    .any(|o| o.capability.as_deref() == Some(capability.as_str()))
            })
            .map(|m| m.control.clone())
            .unwrap_or_default();
        return Decision {
            operations: vec![],
            verdict: Verdict::Refuse {
                missing_capability: Some(capability),
                rule,
            },
        };
    }

    Decision {
        operations: covered,
        verdict: Verdict::Allow,
    }
}

