                    ));
                }
                if !self.inner.router.has(&op.plugin_id, &op.member_name) {
                    return Err(reject(
                        ErrorCode::NotFound,
                        format!(
                            "no handler registered for '{} {}'",
                            op.plugin_id, op.member_name
                        ),
                    ));
                }
                Ok(())
            }
        }
